// Source of truth: logic/hours.js. Quiet hours wrap midnight, so this is not a
// simple range check.
const HOURS_DEFAULTS = {
  timezone: 'UTC',
  business_days: [1, 2, 3, 4, 5],
  business_start_hour: 9,
  business_end_hour: 17,
  quiet_start_hour: 21,
  quiet_end_hour: 8
};
const cfg = Object.assign({}, HOURS_DEFAULTS, {
  timezone: $env.BUSINESS_TIMEZONE || HOURS_DEFAULTS.timezone,
  quiet_start_hour: Number($env.QUIET_START_HOUR || HOURS_DEFAULTS.quiet_start_hour),
  quiet_end_hour: Number($env.QUIET_END_HOUR || HOURS_DEFAULTS.quiet_end_hour)
});
function localParts(when) {
  const fmt = new Intl.DateTimeFormat('en-US', { timeZone: cfg.timezone, hour12: false,
    weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
  const p = {};
  fmt.formatToParts(new Date(when)).forEach((x) => { p[x.type] = x.value; });
  const dow = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }[p.weekday];
  return { year: +p.year, month: +p.month, day: +p.day, hour: (+p.hour) % 24, minute: +p.minute, dow };
}
function fromLocal(parts) {
  const guess = Date.UTC(parts.year, parts.month - 1, parts.day, parts.hour, parts.minute || 0);
  let ts = guess;
  for (let i = 0; i < 3; i++) {
    const p = localParts(new Date(ts));
    const drift = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute) - guess;
    if (drift === 0) break;
    ts -= drift;
  }
  return new Date(ts);
}
function isQuiet(when) {
  const p = localParts(when);
  const s = cfg.quiet_start_hour; const e = cfg.quiet_end_hour;
  if (s === e) return false;
  return s < e ? (p.hour >= s && p.hour < e) : (p.hour >= s || p.hour < e);
}
const now = new Date();
return $input.all().map((item) => {
  const quiet = isQuiet(now);
  let sendAfter = now.toISOString();
  if (quiet) {
    const p = localParts(now);
    const rollsOver = cfg.quiet_start_hour > cfg.quiet_end_hour && p.hour >= cfg.quiet_start_hour;
    const base = fromLocal({ year: p.year, month: p.month, day: p.day, hour: 12, minute: 0 });
    const t = rollsOver ? localParts(new Date(base.getTime() + 24 * 3600 * 1000)) : p;
    sendAfter = fromLocal({ year: t.year, month: t.month, day: t.day, hour: cfg.quiet_end_hour, minute: 0 }).toISOString();
  }
  return { json: Object.assign({}, item.json, { quiet_hours: quiet, send_now: !quiet, send_after: sendAfter }) };
});

